# ===== backtest/rolling_ablation.py =====
EMBEDDED_SOURCES['backtest/rolling_ablation.py']=r'''from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
from typing import Mapping, Sequence

from futures_trend_quant.config import default_config_path, load_config

from .ablation import generate_sprint2_cases
from .development_run import run_rolling_trend_layer


TREND_AFFECTING_KEYS = {
    "rules.div_mode",
    "rules.swing_mode",
    "rules.h1_veto_enabled",
    "rules.h1_strong_atr",
}


def _safe_name(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]+", "-", value).strip("-")


def _matrix_row(
    *,
    name: str,
    key_path: str,
    baseline: object,
    candidate: object,
    status: str,
    report: Mapping[str, object],
) -> dict[str, object]:
    pool = report.get("pool")
    if not isinstance(pool, Mapping):
        raise ValueError(f"trend report for {name} has no pool metrics")
    return {
        "case": name,
        "key_path": key_path,
        "baseline": baseline,
        "candidate": candidate,
        "trend_execution_status": status,
        "trade_layer_status": "BLOCKED_UNVERIFIED_FEES",
        "fact_rows": report.get("fact_rows"),
        "direction_agreement": pool.get("direction_agreement"),
        "direction_agreement_passed": pool.get("direction_agreement_passed"),
        "trend_segment_coverage": pool.get("trend_segment_coverage"),
        "trend_segment_coverage_passed": pool.get("trend_segment_coverage_passed"),
        "range_switches_per_product_day": pool.get("range_switches_per_product_day"),
        "range_switches_passed": pool.get("range_switches_passed"),
        "turn_delay_median": pool.get("turn_delay_median"),
        "turn_delay_passed": pool.get("turn_delay_passed"),
        "unresolved_turn_rate": pool.get("unresolved_turn_rate"),
    }


def run_rolling_ablation(
    *,
    data_root: Path,
    baseline_path: Path,
    report_dir: Path,
    workers: int,
) -> dict[str, object]:
    config = load_config(default_config_path())
    baseline_report = json.loads(baseline_path.read_text(encoding="utf-8"))
    rows = [
        _matrix_row(
            name="BASELINE",
            key_path="",
            baseline=None,
            candidate=None,
            status="REPLAYED",
            report=baseline_report,
        )
    ]
    report_dir.mkdir(parents=True, exist_ok=True)
    for case in generate_sprint2_cases(config.raw):
        if case.key_path not in TREND_AFFECTING_KEYS:
            rows.append(
                _matrix_row(
                    name=case.name,
                    key_path=case.key_path,
                    baseline=case.baseline,
                    candidate=case.candidate,
                    status="TREND_INVARIANT_BY_DESIGN",
                    report=baseline_report,
                )
            )
            continue
        case_path = report_dir / f"{_safe_name(case.name)}.json"
        if case_path.exists():
            report = json.loads(case_path.read_text(encoding="utf-8"))
            status = "REUSED_CHECKPOINT"
        else:
            report, _ = run_rolling_trend_layer(
                data_root,
                workers=workers,
                rules_override=dict(case.config["rules"]),
                dataset_label=f"rolling-180d-20260507-20261102__{case.name}",
            )
            report["ablation"] = {
                "case": case.name,
                "key_path": case.key_path,
                "baseline": case.baseline,
                "candidate": case.candidate,
            }
            case_path.write_text(
                json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            status = "REPLAYED"
        rows.append(
            _matrix_row(
                name=case.name,
                key_path=case.key_path,
                baseline=case.baseline,
                candidate=case.candidate,
                status=status,
                report=report,
            )
        )
    return {
        "schema_version": 1,
        "purpose": "SPRINT2_ROLLING_180D_ONE_AT_A_TIME_ABLATION",
        "performance_interpretation_allowed": False,
        "dataset_label": "rolling-180d-20260507-20261102",
        "trend_affecting_keys": sorted(TREND_AFFECTING_KEYS),
        "cases": rows,
    }


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Run checkpointed rolling 180-day ablations")
    parser.add_argument("--data-root", type=Path, required=True)
    parser.add_argument("--baseline", type=Path, required=True)
    parser.add_argument("--report-dir", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=1)
    args = parser.parse_args(argv)
    matrix = run_rolling_ablation(
        data_root=args.data_root,
        baseline_path=args.baseline,
        report_dir=args.report_dir,
        workers=args.workers,
    )
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(
        json.dumps(matrix, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(json.dumps({"output": str(args.output), "cases": len(matrix["cases"])}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
'''

# ===== backtest/runner.py =====
EMBEDDED_SOURCES['backtest/runner.py']=r'''from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from datetime import date
from typing import Callable, Iterable, Mapping, Protocol

from futures_trend_quant.core.models import Bar

from .aggregation import SequentialAggregator
from .execution import apply_position_management, close_position_at_market, match_exit_in_bar, open_position
from .models import FeeSchedule, Fill, Position, SignalIntent, Trade


@dataclass(frozen=True)
class ReplayBar:
    bar: Bar
    trading_date: date


@dataclass(frozen=True)
class StepInput:
    symbol: str
    trading_date: date
    m15_bar: Bar
    m5_bars: tuple[Bar, ...]
    m15_bars: tuple[Bar, ...]
    position: Position | None
    m1_bars: tuple[Bar, ...] = ()
    positions: tuple[Position, ...] = ()


@dataclass(frozen=True)
class StepOutput:
    signal: SignalIntent | None = None
    facts: Mapping[str, object] = field(default_factory=dict)
    blocked_at: str | None = None
    close_reason: str | None = None


class StrategyStep(Protocol):
    def __call__(self, event: StepInput) -> StepOutput: ...


@dataclass(frozen=True)
class FactRecord:
    symbol: str
    eob: object
    values: Mapping[str, object]


@dataclass
class BacktestResult:
    trades: list[Trade] = field(default_factory=list)
    fills: list[Fill] = field(default_factory=list)
    facts: list[FactRecord] = field(default_factory=list)
    blocked_at: list[str] = field(default_factory=list)
    open_positions: dict[str, tuple[Position, ...]] = field(default_factory=dict)


class OfflineRunner:
    """Deterministic M1 event loop with injected strategy core.

    The runner deliberately refuses to start when fee schedules are not marked
    verified.  This prevents a seemingly successful PnL report from being
    produced with placeholder costs.
    """

    def __init__(
        self,
        *,
        fees: Mapping[str, FeeSchedule],
        strategy_step: StrategyStep | None,
        require_verified_fees: bool = True,
        history_limit: int = 1600,
    ) -> None:
        if strategy_step is None:
            raise ValueError("strategy_step is required; refusing a no-op backtest")
        if history_limit < 100:
            raise ValueError("history_limit must be at least 100")
        if not fees:
            raise ValueError("at least one fee schedule is required")
        if require_verified_fees:
            unverified = sorted(product for product, spec in fees.items() if not spec.verified)
            if unverified:
                raise ValueError(f"unverified fee schedules: {', '.join(unverified)}")
        self.fees = dict(fees)
        self.strategy_step = strategy_step
        self.history_limit = history_limit

    def run(self, events: Iterable[ReplayBar]) -> BacktestResult:
        m5_agg = SequentialAggregator(5, "300s")
        m15_agg = SequentialAggregator(15, "900s")
        m5_history: dict[str, list[Bar]] = defaultdict(list)
        m15_history: dict[str, list[Bar]] = defaultdict(list)
        m1_history: dict[str, list[Bar]] = defaultdict(list)
        positions: dict[str, list[Position]] = defaultdict(list)
        pending: dict[str, SignalIntent] = {}
        pending_closes: dict[str, str] = {}
        result = BacktestResult()

        ordered = sorted(events, key=lambda item: (item.bar.eob, item.bar.symbol))
        last_eob: dict[str, object] = {}
        for event in ordered:
            bar = event.bar
            product = _product_from_symbol(bar.symbol)
            if product not in self.fees:
                raise ValueError(f"missing fee schedule for {product}")
            fees = self.fees[product]
            previous = last_eob.get(bar.symbol)
            if previous is not None and bar.eob <= previous:  # type: ignore[operator]
                raise ValueError(f"non-increasing bars for {bar.symbol}")
            last_eob[bar.symbol] = bar.eob

            m1_history[bar.symbol].append(bar)
            del m1_history[bar.symbol][:-self.history_limit]

            close_reason = pending_closes.pop(bar.symbol, None)
            if close_reason:
                for position in positions[bar.symbol]:
                    fill, trade = close_position_at_market(
                        position, bar, fees, trading_date=event.trading_date, reason=close_reason
                    )
                    result.fills.append(fill)
                    result.trades.append(trade)
                positions[bar.symbol].clear()

            remaining: list[Position] = []
            for position in positions[bar.symbol]:
                matched = match_exit_in_bar(position, bar, fees, trading_date=event.trading_date)
                if matched is None and apply_position_management(position, bar):
                    matched = match_exit_in_bar(position, bar, fees, trading_date=event.trading_date)
                if matched is not None:
                    fill, trade = matched
                    result.fills.append(fill)
                    result.trades.append(trade)
                else:
                    remaining.append(position)
            positions[bar.symbol] = remaining

            intent = pending.pop(bar.symbol, None)
            if intent is not None and (not positions[bar.symbol] or intent.allow_stack):
                raw_price = intent.entry_price if intent.entry_price is not None else bar.open
                position, fill = open_position(
                    symbol=bar.symbol,
                    side=intent.side,
                    volume=intent.volume,
                    raw_price=raw_price,
                    stop_price=intent.stop_price,
                    target_price=intent.target_price,
                    opened_at=bar.bob,
                    trading_date=event.trading_date,
                    path=intent.path,
                    fees=fees,
                    evidence_id=intent.evidence_id,
                    signal_m15_index=intent.signal_m15_index,
                    pm_mode=intent.pm_mode,
                )
                positions[bar.symbol].append(position)
                result.fills.append(fill)
                matched = match_exit_in_bar(position, bar, fees, trading_date=event.trading_date)
                if matched is None and apply_position_management(position, bar):
                    matched = match_exit_in_bar(position, bar, fees, trading_date=event.trading_date)
                if matched is not None:
                    exit_fill, trade = matched
                    result.fills.append(exit_fill)
                    result.trades.append(trade)
                    positions[bar.symbol].remove(position)

            m5_closed = m5_agg.update(bar)
            if m5_closed is not None:
                m5_history[bar.symbol].append(m5_closed)
                del m5_history[bar.symbol][:-self.history_limit]
            m15_closed = m15_agg.update(bar)
            if m15_closed is None:
                continue
            m15_history[bar.symbol].append(m15_closed)
            del m15_history[bar.symbol][:-self.history_limit]
            output = self.strategy_step(
                StepInput(
                    symbol=bar.symbol,
                    trading_date=event.trading_date,
                    m15_bar=m15_closed,
                    m5_bars=tuple(m5_history[bar.symbol]),
                    m15_bars=tuple(m15_history[bar.symbol]),
                    position=positions[bar.symbol][0] if positions[bar.symbol] else None,
                    m1_bars=tuple(m1_history[bar.symbol]),
                    positions=tuple(positions[bar.symbol]),
                )
            )
            if not isinstance(output, StepOutput):
                raise TypeError("strategy_step must return StepOutput")
            result.facts.append(FactRecord(bar.symbol, m15_closed.eob, dict(output.facts)))
            if output.blocked_at:
                result.blocked_at.append(output.blocked_at)
            if output.close_reason:
                pending_closes[bar.symbol] = output.close_reason
                pending.pop(bar.symbol, None)
            if output.signal is not None:
                if output.signal.symbol != bar.symbol:
                    raise ValueError("strategy signal symbol does not match event")
                if (positions[bar.symbol] and not output.signal.allow_stack) or bar.symbol in pending:
                    result.blocked_at.append("POSITION_EXISTS")
                else:
                    pending[bar.symbol] = output.signal

        result.open_positions = {
            symbol: tuple(items) for symbol, items in positions.items() if items
        }
        return result


def _product_from_symbol(symbol: str) -> str:
    tail = symbol.split(".")[-1]
    letters = "".join(char for char in tail if char.isalpha())
    if not letters:
        raise ValueError(f"cannot derive product from symbol {symbol!r}")
    return letters.upper()
'''

# ===== backtest/sizing_table.py =====
EMBEDDED_SOURCES['backtest/sizing_table.py']=r'''from __future__ import annotations

from dataclasses import dataclass
from math import floor
from typing import Iterable


@dataclass(frozen=True)
class ProductSizingInput:
    product: str
    multiplier: float
    price_tick: float
    median_price: float
    atr14: float
    average_daily_volume: float
    estimated_round_trip_cost_per_lot: float

    def __post_init__(self) -> None:
        values = (
            self.multiplier,
            self.price_tick,
            self.median_price,
            self.atr14,
            self.average_daily_volume,
        )
        if any(value <= 0 for value in values):
            raise ValueError("sizing inputs must be positive and derived from actual history")
        if self.estimated_round_trip_cost_per_lot < 0:
            raise ValueError("cost cannot be negative")


def lots_for_stop(
    item: ProductSizingInput,
    *,
    capital: float,
    risk_pct: float,
    stop_atr: float,
    adv_fraction: float = 0.001,
) -> dict[str, float | int | bool]:
    if capital <= 0 or not 0 < risk_pct <= 0.01 or stop_atr <= 0:
        raise ValueError("invalid capital, risk_pct, or stop_atr")
    risk_per_lot = item.atr14 * stop_atr * item.multiplier + item.estimated_round_trip_cost_per_lot
    risk_lots = floor(capital * risk_pct / risk_per_lot)
    liquidity_cap = floor(item.average_daily_volume * adv_fraction)
    final_lots = max(0, min(risk_lots, liquidity_cap))
    return {
        "capital": capital,
        "risk_budget": capital * risk_pct,
        "stop_atr": stop_atr,
        "risk_per_lot": risk_per_lot,
        "risk_lots": risk_lots,
        "adv_cap_lots": liquidity_cap,
        "final_lots": final_lots,
        "tradable": final_lots >= 1,
    }


def build_sizing_matrix(
    inputs: Iterable[ProductSizingInput],
    *,
    capitals: tuple[float, ...] = (500_000.0, 1_000_000.0, 2_000_000.0),
    stop_atrs: tuple[float, ...] = (1.5, 3.0, 6.0),
    risk_pct: float = 0.01,
) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for item in inputs:
        for capital in capitals:
            for stop_atr in stop_atrs:
                rows.append(
                    {
                        "product": item.product,
                        "multiplier": item.multiplier,
                        "price_tick": item.price_tick,
                        "median_price": item.median_price,
                        "atr14": item.atr14,
                        "average_daily_volume": item.average_daily_volume,
                        **lots_for_stop(
                            item,
                            capital=capital,
                            risk_pct=risk_pct,
                            stop_atr=stop_atr,
                        ),
                    }
                )
    return rows
'''

