sys.path.insert(0,str(ROOT))
from backtest.forward_v3 import read,write,digest
from tools.first_entry_v71.admission import admit,DEFAULT_LOCK
from tools.first_entry_v71.clock import AdmissionError,timestamp,anchor_rows,object_hash
from tools.first_entry_v7.selector import frame_from_v6,filter_frames
from tools.historical_strategy.analyze import extract,match_controls


def serializable(value):
    return json.loads(json.dumps(value,default=str,allow_nan=False))


def select(context,output):
    reg=read(ROOT/'tools/first_entry_v7/registration.json')
    rules=read(ROOT/'config/strategy.json')['rules'];fees=read(ROOT/'config/fees.json')['products']
    start,end=timestamp(context['lock']['first_scoring_eob']),timestamp(context['lock']['last_scoring_eob'])
    frames=[];opportunities=[];controls=[]
    for (cs,symbol),traces in sorted(context['traces'].items()):
        task=dict(csymbol=cs,symbol=symbol)
        tick=fees[cs.split('.')[1]]['price_tick']
        ops,ordinary,_,_=extract(task,traces,tick,rules)
        opportunities.extend(r for r in ops if start<=r['time']<=end)
        controls.extend(r for r in ordinary if start<=r['time']<=end)
        ordinals={timestamp(r['eob']):i for i,r in enumerate(context['anchors'][cs])}
        previous=None;previous_state=None;episode=0
        for index,row in enumerate(traces):
            now=timestamp(row['decision_eob']);state=row['groups']['S0']['trend_decision']['state']['trend_state']
            episode+=state!=previous_state
            contiguous=previous is None or ordinals[now]-ordinals[previous]==1
            frames.append(frame_from_v6(task,row,index,tick,rules,in_scoring_window=start<=now<=end,
                contiguous=contiguous,v6_episode=episode))
            previous,previous_state=now,state
    decisions,episodes=filter_frames(frames)
    for episode in episodes:
        marker='' if episode['start_known'] else 'LEFT_CENSORED@'
        episode['episode_id']='|'.join((episode['csymbol'],episode['actual_contract'],episode['direction'],marker+episode['start_eob']))
    decision_index={}
    for row in decisions:
        if row['reason'] in ('KEEP','PRE_SAMPLE_CONSUMED','EPISODE_SLOT_ALREADY_CONSUMED','LEFT_CENSORED_FIRST_UNKNOWN'):
            decision_index.setdefault(row['opportunity_id'],row)
    opportunities.sort(key=lambda r:(r['time'],r['csymbol'],r['actual_contract'],r['opportunity_id']))
    for row in opportunities:
        decision=decision_index[row['opportunity_id']]
        row.update(first_selected=decision['kept'],episode_id=decision['episode_id'],selection_reason=decision['reason'])
    fixed_pairs=match_controls(opportunities,controls)  # All S0 once; no outcome exists yet.
    payloads=dict(opportunities=opportunities,controls=controls,fixed_control_pairs=fixed_pairs,
                  decisions=decisions,episodes=episodes,coverage=context['coverage'])
    output.mkdir(parents=True,exist_ok=False)
    selection_dir=output/'selection';selection_dir.mkdir()
    hashes={}
    for name,value in payloads.items():
        value=serializable(value)
        write(selection_dir/(name+'.json'),value)
        hashes[name]=object_hash(value)
    receipt=dict(status='SELECTED_NOT_SCORED' if opportunities else 'SELECTED_NO_OPPORTUNITIES',
        purpose=context['lock']['purpose'],selection_object_sha256=hashes,
        sample_lock_sha256=object_hash(context['lock']),s0_opportunities=len(opportunities),
        first_selected=sum(r['first_selected'] for r in opportunities),fixed_matches=len(fixed_pairs),
        expected_m15=sum(r['expected_m15'] for r in context['coverage']),
        qualified_m15=sum(r['qualified_frames'] for r in context['coverage']),no_orders=True,
        future_labels_read=False)
    write(selection_dir/'receipt.json',receipt)
    return receipt


def run(manifest_path,input_root,output,sample_lock=DEFAULT_LOCK,fixture=False,score=False):
    if output.exists():
        raise AdmissionError('OUTPUT_ALREADY_EXISTS_USE_NEW_AUDITED_RUN')
    context=admit(manifest_path,input_root,sample_lock,fixture)
    receipt=select(context,output)
    if score:
        from tools.first_entry_v71.scoring import score_once
        summary=score_once(context,output)
        return dict(receipt,status='SCORED',decision=summary['verdict']['decision'])
    return receipt


def main():
    p=argparse.ArgumentParser()
    p.add_argument('--manifest',type=Path,required=True)
    p.add_argument('--input-root',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True)
    p.add_argument('--sample-lock',type=Path,default=DEFAULT_LOCK)
    p.add_argument('--fixture',action='store_true')
    p.add_argument('--score',action='store_true')
    a=p.parse_args()
    try:
        receipt=run(a.manifest,a.input_root,a.output,a.sample_lock,a.fixture,a.score)
        print(receipt['status'],receipt['qualified_m15'],flush=True)
    except (AdmissionError,KeyError,ValueError,OSError) as exc:
        # A failed admission has diagnostics only, never a selection/score success receipt.
        path=a.output.parent/(a.output.name+'_failure.json')
        if not path.exists():
            path.parent.mkdir(parents=True,exist_ok=True)
            coverage=[]
            try:
                lock=read(a.sample_lock)
                for cs,product in lock.get('products',{}).items():
                    detail=getattr(exc,'detail',{})
                    affected=detail.get('csymbol')==cs
                    coverage.append(dict(csymbol=cs,expected_m15=product['expected_scoring_m15'],
                        actual_frames=detail.get('received',detail.get('actual_frames')) if affected else None,
                        qualified_frames=detail.get('qualified_frames') if affected else None,
                        state='FAILED_AT_REPORTED_STAGE' if affected else 'NOT_ASSESSED_OR_NOT_COMPLETED'))
            except (OSError,KeyError,ValueError):pass
            write(path,dict(status='READY_FOR_DATA' if 'READY_FOR_DATA' in str(exc) or getattr(exc,'code','')=='SAMPLE_LOCK_NOT_FROZEN' else 'DATA_NOT_QUALIFIED',
                code=getattr(exc,'code',type(exc).__name__),detail=getattr(exc,'detail',{}),
                coverage_by_product=coverage,success_receipt_written=False,no_orders=True))
        print('FAILED',getattr(exc,'code',type(exc).__name__),flush=True)
        raise SystemExit(2)


if __name__=='__main__':main()
'''

# ===== tools/first_entry_v71/fetch_warmup_v712.py =====
EMBEDDED_SOURCES['tools/first_entry_v71/fetch_warmup_v712.py']=r'''"""Fetch two fixed pre-scoring EDB ranges. Python 3.9+, standard library only."""
import argparse
import csv
import hashlib
import io
from http.client import HTTPException
import json
import tempfile
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from pathlib import Path
from urllib.error import HTTPError
from urllib.parse import urlencode
from urllib.request import Request, urlopen

RECEIPT_SHA = '3b1ddff678000812823424a04985c46d4ce32457a8c0d13dd7124e6c49e97b97'
CUT = '2025-11-05T15:00:00+08:00'
CN = timezone(timedelta(hours=8))
LEGS = {'DCE.jd2602': 9000, 'DCE.eg2605': 13800}
FULL = ('open', 'high', 'low', 'close', 'volume', 'open_oi', 'close_oi')
EDB = 'https://edb.shinnytech.com/md/kline'


def sha(data):
    return hashlib.sha256(data).hexdigest()


def expected_minutes(leg):
    expected = set()
    for gap in leg['missing_intervals_proxy']:
        if gap['last_eob'] <= CUT:
            continue
        first = datetime.fromisoformat(gap['first_eob'])
        last = datetime.fromisoformat(gap['last_eob'])
        if gap['first_eob'] <= CUT or last != first + timedelta(minutes=gap['minutes'] - 1):
            raise ValueError('unexpected gap boundaries')
        expected.update(int(first.timestamp()) + 60 * i for i in range(gap['minutes']))
    if len(expected) != LEGS[leg['actual_contract']]:
        raise ValueError('gap inventory differs from the reviewed contract')
    return expected


def inspect_csv(data, expected, fields):
    rows = csv.DictReader(io.StringIO(data.decode('utf-8-sig')))
    if rows.fieldnames is None or not {'datetime_nano', *fields} <= set(rows.fieldnames):
        raise ValueError('missing EDB fields')
    observed = []
    zero = 0
    for row in rows:
        bob_ns = int(row['datetime_nano'])
        if bob_ns % 60_000_000_000:
            raise ValueError('timestamp is not minute-aligned')
        observed.append(bob_ns // 1_000_000_000 + 60)
        v = {f: Decimal(row[f]) for f in fields}
        if not all(n.is_finite() for n in v.values()) or v['volume'] < 0:
            raise ValueError('nonfinite value or negative volume')
        zero += v['volume'] == 0
        if fields == FULL:
            if min(v['open_oi'], v['close_oi']) < 0:
                raise ValueError('negative open interest')
            if not (v['low'] <= min(v['open'], v['close']) <= max(v['open'], v['close']) <= v['high']):
                raise ValueError('inconsistent OHLC')
    unique = set(observed)
    return dict(rows=len(observed), duplicates=len(observed)-len(unique),
                missing=len(expected-unique), extra=len(unique-expected),
                time_sorted=observed == sorted(observed), zero_volume_rows=zero)


def fetch(symbol, expected, fields, folder, item):
    def wall(second):
        return datetime.fromtimestamp(second, CN).strftime('%Y-%m-%d %H:%M:%S')
    params = dict(symbol=symbol, period=60, start_time=wall(min(expected)-60),
                  end_time=wall(max(expected)), col=','.join(fields))
    item.update(request=params, expected=len(expected), requested_at=datetime.now(timezone.utc).isoformat())
    request = Request(EDB + '?' + urlencode(params))
    try:
        with urlopen(request, timeout=60) as response:
            item['http_status'] = response.status
            data = response.read()
    except HTTPError as exc:
        item['http_status'] = exc.code
        data = exc.read()
        (folder / (symbol + '.error')).write_bytes(data)
        item['response_sha256'] = sha(data)
        raise
    item['response_sha256'] = sha(data)
    if fields == FULL:
        filename = symbol + '.csv'
        (folder / filename).write_bytes(data)
        item['raw_file'] = filename
    item.update(inspect_csv(data, expected, fields))
    if item['duplicates'] or item['missing'] or item['extra'] or not item['time_sorted']:
        raise ValueError('minutes failed exact coverage or ordering')
    item['status'] = 'RAW_RANGE_CHECKED' if fields == FULL else 'CLOCK_ONLY_CHECKED'


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo', type=Path, required=True)
    p.add_argument('--clock-only', action='store_true', help='request only volume and time, retain counts and hash')
    args = p.parse_args()
    repo = args.repo.resolve()
    original = (repo / 'reports/v711_warmup_receipts.json').read_bytes()
    if sha(original.replace(b'\r\n', b'\n')) != RECEIPT_SHA:
        p.error('expected the published v711_warmup_receipts.json from 1df7180')
    legs = {r['actual_contract']: r for r in json.loads(original)['legs']}
    root = repo / 'data/cache/v711_edb_supplement'
    root.mkdir(parents=True, exist_ok=True)
    folder = Path(tempfile.mkdtemp(prefix='clock_' if args.clock_only else 'raw_', dir=root))
    report = dict(study_status='READY_FOR_DATA', historical_sessions='UNVERIFIED_PROXY',
                  purpose='WARMUP_COVERAGE_ONLY', source=EDB, baseline_receipt_lf_sha256=RECEIPT_SHA,
                  expected_source_clock='M1_START_NS', strict_qualified_legs_claimed=0, real_score_runs=0, legs=[])
    for symbol in LEGS:
        item = dict(symbol=symbol, status='FAILED')
        try:
            fetch(symbol, expected_minutes(legs[symbol]), ('volume',) if args.clock_only else FULL, folder, item)
        except (OSError, HTTPException, csv.Error, ValueError, KeyError, ArithmeticError) as exc:
            item['error'] = type(exc).__name__ + ': ' + str(exc)
        report['legs'].append(item)
        (folder / 'receipt.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
        print(symbol, item['status'], 'rows', item.get('rows'), flush=True)
    print(folder / 'receipt.json')
    return int(any(x['status'] == 'FAILED' for x in report['legs']))


if __name__ == '__main__':
    raise SystemExit(main())
'''

# ===== tools/first_entry_v71/fixtures.py =====
EMBEDDED_SOURCES['tools/first_entry_v71/fixtures.py']=r'''"""Synthetic full-pool CLI fixtures; never historical strategy evidence."""
import gzip,json
from pathlib import Path
import pandas as pd
from backtest.forward_v3 import read,write,digest
from tools.historical_strategy.reproduce import canonical_digest
from tools.first_entry_v71.clock import dates,calendar_clock,anchor_rows,make_lock,object_hash,timestamp,DAY_SESSIONS,NIGHT_END

ROOT=Path(__file__).resolve().parents[2]


def rehash_inputs(folder):
    """Re-freeze a distinct synthetic input mutation before its first CLI run."""
    manifest=read(folder/'manifest.json');calendar=read(folder/'calendar.json');lock=read(folder/'sample_lock.json')
    assert calendar['purpose']=='ENGINEERING_FIXTURE_ONLY'
    hashes={p['path']:digest(folder/p['path']) for p in calendar['evidence_files']}
    for product in manifest['products'].values():
        for kind in ('schedule','selection'):
            relative=product[kind+'_path'];product[kind+'_sha256']=digest(folder/relative);hashes[relative]=product[kind+'_sha256']
        for contract in product['contracts']:
            raw_hash=digest(folder/contract['raw_path'])
            replay=folder/contract['replay_path']
            with gzip.open(replay,'rt',encoding='utf8') as stream:
                header=json.loads(next(stream));tail=stream.read()
            if header.get('input_sha256')!=raw_hash:
                header['input_sha256']=raw_hash
                with gzip.open(replay,'wt',encoding='utf8') as stream:stream.write(json.dumps(header)+'\n'+tail)
            for kind in ('raw','replay'):
                relative=contract[kind+'_path'];contract[kind+'_sha256']=digest(folder/relative);hashes[relative]=contract[kind+'_sha256']
    calendar['input_file_sha256']=hashes;write(folder/'calendar.json',calendar)
    lock.update(calendar_sha256=digest(folder/'calendar.json'),input_file_sha256=hashes)
    write(folder/'sample_lock.json',lock)
    manifest['sample_lock_sha256']=object_hash(lock);write(folder/'manifest.json',manifest)


def reseal(folder):
    manifest=read(folder/'manifest.json');calendar=read(folder/'calendar.json')
    hashes={}
    for proof in calendar['evidence_files']:
        proof['sha256']=digest(folder/proof['path']);hashes[proof['path']]=proof['sha256']
    for cs,product in manifest['products'].items():
        for kind in ('schedule','selection'):
            relative=product[kind+'_path'];product[kind+'_sha256']=digest(folder/relative);hashes[relative]=product[kind+'_sha256']
        for contract in product['contracts']:
            for kind in ('raw','replay'):
                relative=contract[kind+'_path'];contract[kind+'_sha256']=digest(folder/relative);hashes[relative]=contract[kind+'_sha256']
    calendar['input_file_sha256']=hashes;write(folder/'calendar.json',calendar)
    registration=read(ROOT/'tools/first_entry_v7/registration.json')
    lock=make_lock(calendar,registration,canonical_digest(ROOT/'tools/first_entry_v7/registration.json'),digest(folder/'calendar.json'))
    write(folder/'sample_lock.json',lock)
    manifest.update({key:lock[key] for key in ('registration_sha256','source_policy','first_scoring_eob','last_scoring_eob','last_path_eob')})
    manifest['sample_lock_sha256']=object_hash(lock)
    for cs,product in manifest['products'].items():product['scoring_trade_dates']=lock['products'][cs]['scoring_trade_dates']
    write(folder/'manifest.json',manifest)
    return manifest,lock


def build(folder,zero_opportunities=False):
    folder.mkdir(parents=True,exist_ok=False)
    reg=read(ROOT/'tools/first_entry_v7/registration.json')
    # Full civil-day records intentionally use a synthetic weekday calendar.
    records=[];previous=None
    for day in dates('2025-06-01','2026-05-06'):
        opened=pd.Timestamp(day).weekday()<5
        records.append(dict(date=day,is_open=opened,night_start_date=previous if opened else None))
        if opened:previous=day
    proof=folder/'fixture_proof.json';write(proof,dict(purpose='ENGINEERING_FIXTURE_ONLY',not_official_calendar=True))
    calendar=dict(coverage_start='2025-06-01',coverage_end='2026-05-06',purpose='ENGINEERING_FIXTURE_ONLY',
        independent_of_quote_minutes=True,evidence_files=[dict(path=proof.name,sha256=digest(proof))],
        source_policy=dict(source='SYNTHETIC',mapping='SYNTHETIC_CONSTANT_ACTUAL_LEG',arrival_at='UNKNOWN',
            zero_volume='KEEP_ORIGINAL_NO_FILL',volume='LOTS',position='END_OI'),products={})
    products={}
    for cs in reg['new_sample']['universe']:
        product_days=[dict(r,night_start_date=r['night_start_date'] if cs in NIGHT_END else None) for r in records]
        calendar['products'][cs]=dict(days=product_days,day_sessions=[list(x) for x in DAY_SESSIONS],night_end=NIGHT_END.get(cs))
        clock=calendar_clock(calendar,cs);anchors=anchor_rows(clock)
        symbol=cs+'.SYNTHETIC';prefix=cs.replace('.','_')
        schedule_path=folder/(prefix+'_schedule.json');write(schedule_path,[dict(eob=r['eob'],trading_date=r['trading_date']) for r in clock])
        selection_path=folder/(prefix+'_selection.json');write(selection_path,{r['date']:symbol for r in product_days if r['is_open']})
        eobs=pd.DatetimeIndex([r['eob'] for r in clock if r['eob']>='2025-09-01'])
        raw=pd.DataFrame(dict(symbol=symbol,bob=eobs-pd.Timedelta(minutes=1),eob=eobs,
            open=100.,high=101.,low=99.,close=100.,volume=1.,position=100.))
        if cs=='DCE.M' and not zero_opportunities:
            raw.loc[raw.eob==timestamp('2026-01-05T09:16:00+08:00'),'high']=109.
            raw.loc[(raw.eob>timestamp('2026-01-05T09:30:00+08:00'))&(raw.eob<timestamp('2026-01-09T15:01:00+08:00')),'low']=95.
        raw_path=folder/(prefix+'.parquet');raw.to_parquet(raw_path,index=False)
        replay_path=folder/(prefix+'.jsonl.gz')
        with gzip.open(replay_path,'wt',encoding='utf8') as stream:
            stream.write(json.dumps(dict(task=dict(csymbol=cs,symbol=symbol),input_sha256=digest(raw_path)))+'\n')
            for index,anchor in enumerate(anchors):
                time=timestamp(anchor['eob'])
                if time<timestamp('2025-09-01T00:00:00+08:00'):continue
                if time>timestamp('2026-04-24T15:00:00+08:00'):break
                is_bull=cs=='DCE.M' and not zero_opportunities and timestamp('2026-01-05T09:15:00+08:00')<=time<=timestamp('2026-01-05T10:15:00+08:00')
                accepted=is_bull and time.minute in (15,30) and time.hour==9
                entry=dict(accepted=accepted,gate_open=True,formed_paths=['D'] if accepted else [],reason='PASS' if accepted else 'NO_PATH')
                if accepted:entry.update(path='D',evidence_id='evidence_'+time.isoformat(),trigger_bar_id=time.isoformat(),anchor=dict(anchor_price=98.))
                core=dict(close=100.,atr14=2.,trend_decision=dict(state=dict(trend_state='bull' if is_bull else 'none')),entry_evaluation=entry)
                bar=dict(symbol=symbol,bob=(time-pd.Timedelta(minutes=15)).isoformat(),eob=time.isoformat(),frequency='900s',open=100.,high=101.,low=99.,close=100.,volume=15.,position=100.)
                row=dict(decision_eob=time.isoformat(),bar=bar,complete_m15=True,selected=True,
                    trading_date=anchor['trading_date'],groups=dict(S0=core),i15=index)
                stream.write(json.dumps(row)+'\n')
        products[cs]=dict(schedule_path=schedule_path.name,selection_path=selection_path.name,
            contracts=[dict(symbol=symbol,raw_path=raw_path.name,replay_path=replay_path.name)])
    write(folder/'calendar.json',calendar)
    write(folder/'manifest.json',dict(status='QUALIFIED_BEFORE_SCORING',registered_before_labels=True,
        calendar_path='calendar.json',products=products))
    return reseal(folder)


if __name__=='__main__':
    import sys
    build(Path(sys.argv[1]),'--zero' in sys.argv[2:])
    print('SYNTHETIC_FULL_POOL_BUILT',flush=True)
