EMBEDDED_SOURCES['tools/mechanism_preflight/features.py']=r'''"""Past-only session features. No future response, first-touch or P&L API exists."""
from datetime import timedelta
import hashlib
import numpy as np
import pandas as pd
import pyarrow.dataset as ds
from .common import ALLOWED_PRICE_COLUMNS,authorize_price_span,result_columns,sha


def read_prefixes(item,policy,days,signal_clock='14:30'):
    if not item.get('engineering_price_access') or not authorize_price_span(policy,item.get('min_event_at'),item.get('max_event_at'),item.get('purpose')):
        raise ValueError('protected price body blocked before loader')
    if sha(item['path'])!=item['sha256']:raise ValueError('source changed after inventory')
    dataset=ds.dataset(item['path'],format='parquet')
    if result_columns(dataset.schema.names):raise ValueError('result columns forbidden before materialization')
    if not set(ALLOWED_PRICE_COLUMNS)<=set(dataset.schema.names):raise ValueError('M1 required fields missing')
    predicate=None
    for day in days:
        begin=pd.Timestamp(day+'T09:01:00+08:00');end=pd.Timestamp(day+'T09:30:00+08:00');ref=pd.Timestamp(day+'T'+signal_clock+':00+08:00')
        part=((ds.field('eob')>=begin.to_pydatetime())&(ds.field('eob')<=end.to_pydatetime()))|(ds.field('eob')==ref.to_pydatetime())
        predicate=part if predicate is None else predicate|part
    if predicate is None:return pd.DataFrame(columns=ALLOWED_PRICE_COLUMNS)
    # Both column projection and timestamp predicate are passed before materialization.
    columns=list(ALLOWED_PRICE_COLUMNS)+(['received_at'] if 'received_at' in dataset.schema.names else [])
    return dataset.to_table(columns=columns,filter=predicate).to_pandas()


def trading_minutes(expected,start,end):
    ends=pd.to_datetime(expected,utc=True);opens=ends-pd.Timedelta(minutes=1)
    return int(((opens>=pd.Timestamp(start))&(opens<pd.Timestamp(end))).sum())


def require_obi5_fields(columns):
    required={f'{side}_{kind}_{level}' for side in ('bid','ask') for kind in ('price','size') for level in range(1,6)}|{'event_at','received_at'}
    missing=sorted(required-set(columns))
    if missing:raise ValueError('OBI5 not testable from M1/L1: missing '+','.join(missing))
    return dict(schema_only=True,continuous_coverage_verified=False)


def session_observation(frame,expected,symbol,day,tick=1.):
    if result_columns(frame.columns):raise ValueError('outcome/result fields cannot be accessed by preflight')
    ready=pd.Timestamp(day+'T14:30:00+08:00');morning=pd.date_range(day+'T09:01:00+08:00',periods=30,freq='min')
    # The API will not inspect prices after the known feature cutoff.
    f=frame.loc[(frame.symbol==symbol)&(pd.to_datetime(frame.eob,utc=True)<=ready)].copy()
    f['eob']=pd.to_datetime(f.eob,utc=True).dt.tz_convert('Asia/Shanghai');duplicates=bool(f.eob.duplicated().any())
    a=f.loc[f.eob.isin(morning)];reference=f.loc[f.eob==ready]
    issues=[]
    if duplicates:issues.append('DUPLICATE_TIMESTAMP')
    if len(a)!=30 or set(a.eob)!=set(morning) or len(reference)!=1:issues.append('MISSING_FEATURE_MINUTES')
    if 'received_at' in f.columns:
        needed=f.loc[f.eob.isin(morning)|(f.eob==ready)]
        reception=pd.to_datetime(needed.received_at,utc=True,errors='coerce')
        naive=any(not pd.isna(x) and pd.Timestamp(x).tzinfo is None for x in needed.received_at)
        if naive or reception.isna().any() or (reception>ready).any():issues.append('UNKNOWN_OR_LATE_INPUT_AT_SIGNAL')
    result=dict(day=day,symbol=symbol,event_at=ready.isoformat(),direction_evidence_event_at=morning[-1].isoformat(),received_at='UNKNOWN',signal_ready_at=ready.isoformat(),
        order_eligible_at=ready.isoformat(),fill_model_at='NOT_COMPUTED',clock_basis='EVENT_TIME_PROXY',
        direction=None,control_direction=None,risk_valid=None,control_risk_valid=None,feature_complete=False,
        historical_mapping_known_at='UNKNOWN; OLD_RESEARCH_ASSUMPTION',latency_status='COMPUTE_ONLY_MEASURABLE_BROKER_DELAY_UNKNOWN',issues=issues)
    ends=pd.to_datetime(expected,utc=True).tz_convert('Asia/Shanghai');opens=ends-pd.Timedelta(minutes=1)
    expiry=pd.Timestamp(day+'T14:55:00+08:00');eligible=opens[(opens>ready)&(opens<expiry)]
    result.update(next_legal_model_entry_at=eligible[0].isoformat() if len(eligible) else None,
        available_tradable_minutes=trading_minutes(expected,eligible[0],expiry) if len(eligible) else 0,
        expiry_at=expiry.isoformat(),natural_minutes_to_expiry=float((expiry-eligible[0]).total_seconds()/60) if len(eligible) else None)
    required=pd.date_range(day+'T14:31:00+08:00',periods=24,freq='min')
    result['adapted_window_compatible']=bool(len(eligible)==24 and not opens.duplicated().any() and set(eligible)==set(required))
    result['window_issue']=None if result['adapted_window_compatible'] else ('NO_ENTRY_WINDOW' if not len(eligible) else 'WINDOW_MISMATCH')
    if issues:return result
    a=a.sort_values('eob');values=a[['open','high','low','close']].to_numpy()
    if not np.isfinite(values).all() or (a.high<a.low).any() or (a.open<a.low).any() or (a.open>a.high).any() or (a.close<a.low).any() or (a.close>a.high).any() or not np.isfinite(reference.close.iloc[0]):
        result['issues']=['INVALID_PAST_PRICE'];return result
    direction=1 if a.close.iloc[-1]>a.open.iloc[0] else -1 if a.close.iloc[-1]<a.open.iloc[0] else 0
    placebo=1 if int.from_bytes(hashlib.sha256(('20261105|'+symbol+'|'+day).encode()).digest()[:8],'big')%2 else -1
    ref=float(reference.close.iloc[0]);low=float(a.low.min())-tick;high=float(a.high.max())+tick
    result.update(candidate_risk_ticks=(ref-low if direction==1 else high-ref)/tick if direction else None,
        control_risk_ticks=(ref-low if placebo==1 else high-ref)/tick)
    result.update(feature_complete=True,direction=direction,control_direction=placebo,
        risk_valid=bool(direction and (ref-low if direction==1 else high-ref)>0),
        control_risk_valid=bool((ref-low if placebo==1 else high-ref)>0),nonzero_direction=direction!=0)
    return result


def classify_sequence(event_times,received_times,ready_times,event_end_times):
    """Quality and nonoverlap helper; no price field is accepted."""
    events=pd.to_datetime(event_times,utc=True);received=pd.to_datetime(received_times,utc=True);ready=pd.to_datetime(ready_times,utc=True)
    seen=set();last_event=None;until=None;rows=[]
    ends=pd.to_datetime(event_end_times,utc=True)
    original=list(zip(event_times,received_times,ready_times,event_end_times))
    for i,(e,r,s,end) in enumerate(zip(events,received,ready,ends)):
        unknown=any(pd.isna(t) or pd.Timestamp(t).tzinfo is None for t in original[i])
        duplicate=e in seen;late=bool(not unknown and (r>s or e>s));out_of_order=bool(last_event is not None and not pd.isna(e) and e<last_event)
        accepted=not unknown and not duplicate and not late and not out_of_order and (until is None or s>=until)
        rows.append(dict(duplicate=duplicate,late=late,out_of_order=out_of_order,unknown_clock=unknown,accepted=accepted))
        seen.add(e)
        if not pd.isna(e):last_event=e if last_event is None else max(e,last_event)
        if accepted:until=end
    return rows
'''

# ===== tools/mechanism_preflight/inventory.py =====
EMBEDDED_SOURCES['tools/mechanism_preflight/inventory.py']=r'''"""Inspect metadata and allowlisted old sparse-quote schemas, never price values."""
from pathlib import Path
import argparse,csv,json
import pandas as pd
import pyarrow.parquet as pq
from .common import read,write,sha,publish,result_columns,authorize_price_span,output_target


def parquet_metadata(path):
    f=pq.ParquetFile(path);columns=f.schema_arrow.names;times=[];symbols=set();frequencies=set()
    for i in range(f.metadata.num_row_groups):
        group=f.metadata.row_group(i)
        for j in range(group.num_columns):
            c=group.column(j);s=c.statistics
            if s is None or not s.has_min_max:continue
            if c.path_in_schema=='eob':times.extend([pd.Timestamp(s.min),pd.Timestamp(s.max)])
            elif c.path_in_schema=='symbol':symbols.update([str(s.min),str(s.max)])
            elif c.path_in_schema=='frequency':frequencies.update([str(s.min),str(s.max)])
    return dict(fields=columns,rows=f.metadata.num_rows,min_event_at=min(times).isoformat() if times else None,
        max_event_at=max(times).isoformat() if times else None,contracts=sorted(symbols),resolution='|'.join(sorted(frequencies)) or 'UNVERIFIED',
        schema_evidence='PARQUET_FOOTER_OBSERVED_NO_PRICE_BODY_READ')


def trusted_sparse_quote_schema(path,item,policy):
    if not item.get('expected_sha256') or sha(path)!=item['expected_sha256'] or not authorize_price_span(policy,item.get('scope_start'),item.get('scope_end'),item.get('purpose')):
        raise ValueError('untrusted or protected sparse pickle refused before deserialization')
    f=pd.read_pickle(path)  # Only own previously hashed/authorized, bounded old-study samples.
    if result_columns(f.columns):raise ValueError('outcome columns in quote source')
    levels=sorted({len(q) for q in f.quotes}) if 'quotes' in f.columns else []
    times=pd.to_datetime(f.created_at,utc=True) if 'created_at' in f.columns else None
    return dict(fields=list(f.columns),rows=len(f),min_event_at=times.min().isoformat() if times is not None and len(f) else None,
        max_event_at=times.max().isoformat() if times is not None and len(f) else None,contracts=item.get('contracts',[]),
        resolution='SPARSE_TICK_5_SECOND_WINDOWS',schema_evidence='TRUSTED_OLD_QUOTE_COLUMNS_CLOCK_AND_DEPTH_COUNTS_ONLY; NO_PRICE_ANALYSIS',
        observed_book_levels=json.dumps(levels),received_at_field_present='received_at' in f.columns,
        continuous_book_verified=False)


def run(source_index,protected,out):
    output_target(out)
    index=read(source_index);policy=read(protected);rows=[]
    for item in index['sources']:
        path=Path(item['path']);row=dict(source_id=item['source_id'],path=str(path),provider=item.get('provider','UNKNOWN'),
            kind=item['kind'],purpose=item.get('purpose','METADATA_ONLY'),authorization=item.get('authorization','UNVERIFIED'),
            redistribution='NOT_AUTHORIZED; RAW_LOCAL_ONLY',arrival_clock=item.get('arrival_clock','UNKNOWN'),
            license_evidence=item.get('license_evidence','USER_LOCAL_RESEARCH_SCOPE; PROVIDER_CONTRACT_NOT_REAUDITED'),
            exists=path.is_file(),price_body_read=False)
        meta=dict(fields=[],rows=None,min_event_at=None,max_event_at=None,contracts=item.get('contracts',[]),resolution='UNKNOWN',schema_evidence='UNVERIFIED_NO_DESERIALIZATION')
        if path.is_file():
            row.update(sha256=sha(path),bytes=path.stat().st_size)
            if item.get('expected_sha256') and row['sha256']!=item['expected_sha256']:raise ValueError('original source digest mismatch')
            if path.suffix.lower()=='.parquet':meta=parquet_metadata(path)
            elif path.suffix.lower()=='.csv':
                for encoding in ('utf-8-sig','gb18030'):
                    try:
                        with path.open(encoding=encoding,newline='') as f:meta['fields']=next(csv.reader(f),[])
                        meta['schema_evidence']='CSV_HEADER_ONLY_'+encoding;break
                    except UnicodeDecodeError:continue
            elif item['kind'] in ('CALENDAR','MAPPING'):
                obj=read(path)
                if item['kind']=='CALENDAR' and isinstance(obj,list) and obj and all(isinstance(r,dict) and 'eob' in r for r in obj):
                    times=[pd.Timestamp(r['eob']) for r in obj]
                    meta.update(fields=['eob','trading_date'],rows=len(obj),min_event_at=min(times).isoformat(),max_event_at=max(times).isoformat(),resolution='EXPECTED_60s')
                elif item['kind']=='MAPPING' and isinstance(obj,dict):
                    meta.update(fields=['trading_date','actual_contract'],rows=len(obj),contracts=sorted({x for x in obj.values() if isinstance(x,str) and x}))
                meta['schema_evidence']='NONPRICE_CALENDAR_OR_MAPPING_OBSERVED'
            elif item['kind']=='SPARSE_ENTRY_QUOTES':
                meta=trusted_sparse_quote_schema(path,item,policy);row['price_body_read']=True
        else:row.update(sha256=None,bytes=None)
        permitted=authorize_price_span(policy,meta['min_event_at'],meta['max_event_at'],row['purpose'])
        forbidden=result_columns(meta['fields'])
        row.update(min_event_at=meta['min_event_at'],max_event_at=meta['max_event_at'],rows=meta['rows'],
            fields=json.dumps(meta['fields']),contracts=json.dumps(meta['contracts']),finest_resolution=meta['resolution'],schema_evidence=meta['schema_evidence'],
            engineering_price_access=bool(permitted and not forbidden and path.suffix.lower()=='.parquet'),
            new_development_access=False,independent_access=False,
            observed_book_levels=meta.get('observed_book_levels','UNKNOWN'),received_at_field_present=meta.get('received_at_field_present',False),
            access_reason='RESULT_COLUMNS_FORBIDDEN' if forbidden else 'OLD_ENGINEERING_EXCEPTION_ONLY' if permitted else 'PROTECTED_OR_UNKNOWN_RANGE_METADATA_ONLY')
        rows.append(row)
    frame=pd.DataFrame(rows)
    def build(stage):
        frame.to_csv(stage/'inventory.csv',index=False)
        write(stage/'index_binding.json',dict(source_index=str(Path(source_index).resolve()),source_index_sha256=sha(source_index),
            protected=str(Path(protected).resolve()),protected_sha256=sha(protected),inventory_sha256=sha(stage/'inventory.csv'),
            price_bodies_read=int(frame.price_body_read.sum()),price_analysis_performed=False,unique_source_hashes=int(frame.sha256.nunique()),indexed_files=len(frame)))
    publish(out,build)
    return dict(indexed_files=len(frame),unique_source_hashes=int(frame.sha256.nunique()),trusted_quote_schema_bodies=int(frame.price_body_read.sum()),price_analysis_performed=False)


def main():
    p=argparse.ArgumentParser();p.add_argument('--source-index',type=Path,required=True);p.add_argument('--protected',type=Path,required=True);p.add_argument('--out',type=Path,required=True)
    a=p.parse_args();print(json.dumps(run(a.source_index,a.protected,a.out)))


if __name__=='__main__':main()
'''

# ===== tools/mechanism_preflight/routing.py =====
EMBEDDED_SOURCES['tools/mechanism_preflight/routing.py']=r'''"""Stage-specific design gates. No route grants response/backtest/order access."""
LEVELS = ('GROSS_DESIGN', 'NET_EXECUTABLE', 'INDEPENDENT_VALIDATION')
GROSS = {
    'required_feature_fields': 'REQUIRED_FEATURE_FIELDS_NOT_QUALIFIED',
    'new_development_window': 'NO_QUALIFIED_NONOVERLAPPING_NEW_DEVELOPMENT_WINDOW',
    'gross_protocol_frozen': 'GROSS_RESPONSE_PROTOCOL_NOT_FROZEN',
    'independent_reservation_plan': 'NO_UNCONTAMINATED_INDEPENDENT_RESERVATION_PLAN',
}
NET = {
    'gross_development_passed': 'GROSS_DEVELOPMENT_NOT_ACCEPTED',
    'entry_exit_quotes': 'ENTRY_AND_EXIT_QUOTE_COVERAGE_ABSENT_AT_CANDIDATE_TIMES',
    'arrival_and_delay': 'SYNCHRONIZED_ARRIVAL_AND_BROKER_DELAY_UNVERIFIED',
    'fees_certified': 'HISTORICAL_FEES_NOT_CERTIFIED',
    'delta_min_registered': 'DELTA_MIN_NOT_REGISTERED_OWNER_REQUESTS_SENSITIVITY_ONLY',
    'capacity_design_complete': 'CAPACITY_IS_BOUND_ONLY_NOT_EFFECTIVE_PAIR_OR_POWER_QUALIFICATION',
}
INDEPENDENT = {
    'separate_independent_window': 'NO_QUALIFIED_SEPARATE_INDEPENDENT_WINDOW',
    'candidate_frozen': 'CANDIDATE_NOT_FROZEN',
    'independent_protocol_frozen': 'INDEPENDENT_PROTOCOL_NOT_FROZEN',
    'net_development_passed': 'NET_DEVELOPMENT_NOT_ACCEPTED',
}


def decide(evidence):
    level = evidence.get('level')
    if level not in LEVELS:
        raise ValueError('unknown research level')
    reasons = []
    if any(evidence.get(k) is not True for k in ('mechanism_complete', 'primary_mechanism_evidence', 'control_defined')):
        status = 'STOP_NO_MECHANISM'
        reasons.append('TRIGGER_WINDOW_EXIT_ANCHOR_CONTROL_OR_PRIMARY_EVIDENCE_INCOMPLETE')
    elif evidence.get('scope_incompatible') is True or evidence.get('capacity_proven_insufficient') is True:
        status = 'NOT_TESTABLE_WITHIN_SCOPE'
        reasons.append('AUTHORIZED_FIXED_SCOPE_CANNOT_SUPPORT_WINDOW_ANCHOR_OR_CAPACITY')
    else:
        requirements = {**GROSS, **(NET if level != 'GROSS_DESIGN' else {}),
                        **(INDEPENDENT if level == 'INDEPENDENT_VALIDATION' else {})}
        reasons = [reason for key, reason in requirements.items() if evidence.get(key) is not True]
        status = 'NEED_DATA_DECISION' if reasons else 'READY_FOR_DEVELOPMENT_DESIGN'
    return dict(status=status, reasons=reasons, economic_pass=False, backtest_permission=False,
        response_run_permission=False, orders_permission=False, research_level=level,
        interpretation='STAGE_RESOURCE_ROUTING_ONLY_NOT_RESEARCH_AUTHORIZATION_OR_PROMOTION')


def by_stage(evidence):
    return {level: decide(dict(evidence, level=level)) for level in LEVELS}
'''

